+  protected void updateHostsFromZooKeeper() throws KeeperException, InterruptedException {
+    if (pathExists || zoo.exists(path)) {
+      pathExists = true;
+      updateHosts(path, zoo.getChildren(path, this));
+    } else {
+      zoo.exists(path, this);
+    }
+  }
